core_reasoning_1:
\section*{Claim}
Let $P_1,\ldots,P_M$ be Wilson-line path operators with common endpoints, and let
\[
A_{ab}:=\left\langle \operatorname{tr}(P_a^\dagger P_b)\right\rangle,\qquad 1\leq a,b\leq M.
\]
Then $A$ is positive semidefinite: for every real vector $c=(c_1,\ldots,c_M)$,
\[
\sum_{a,b=1}^M c_a c_b A_{ab}\geq 0.
\]

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \displaystyle \langle O\rangle := Z^{-1}\int DU\,e^{-S}O,\qquad Z:=\int DU\,e^{-S}>0,\qquad e^{-S}\geq 0.\\[0.8em]
\text{(P2)} & \displaystyle \operatorname{tr}(V^\dagger V)=\sum_{i,j=1}^N |v_{ij}|^2\geq 0\quad\text{for every complex }N\times N\text{ matrix }V=(v_{ij}).\\[0.8em]
\text{(P3)} & \displaystyle U:=\sum_{a=1}^M c_a P_a,\qquad c_a\in\mathbb{R}.\\[0.8em]
\text{(P4)} & \displaystyle A_{ab}:=\left\langle \operatorname{tr}(P_a^\dagger P_b)\right\rangle.
\end{array}
\]

\section*{Derivation}
\begin{align}
\left\langle \operatorname{tr}(U^\dagger U)\right\rangle
&= Z^{-1}\int DU\,e^{-S}\operatorname{tr}(U^\dagger U) && \text{by (P1)}\\
&\geq 0 && \text{by (P1) and (P2)}.\label{hp-positive}
\end{align}
Using the linear combination in (P3),
\begin{align}
U^\dagger
&=\left(\sum_{a=1}^M c_a P_a\right)^\dagger && \text{by (P3)}\\
&=\sum_{a=1}^M c_a P_a^\dagger && \text{because }c_a\in\mathbb{R},\\
U^\dagger U
&=\left(\sum_{a=1}^M c_a P_a^\dagger\right)\left(\sum_{b=1}^M c_b P_b\right) && \text{substitution}\\
&=\sum_{a,b=1}^M c_a c_b P_a^\dagger P_b && \text{distributivity},\\
\left\langle \operatorname{tr}(U^\dagger U)\right\rangle
&=\left\langle \operatorname{tr}\left(\sum_{a,b=1}^M c_a c_b P_a^\dagger P_b\right)\right\rangle && \text{substitution}\\
&=\sum_{a,b=1}^M c_a c_b\left\langle \operatorname{tr}(P_a^\dagger P_b)\right\rangle && \text{linearity of }\operatorname{tr}\text{ and }\langle\cdot\rangle\\
&=\sum_{a,b=1}^M c_a c_b A_{ab} && \text{by (P4)}.\label{hp-quadratic}
\end{align}
Combining \eqref{hp-positive} and \eqref{hp-quadratic},
\begin{align}
\sum_{a,b=1}^M c_a c_b A_{ab}\geq 0\qquad\text{for all }c\in\mathbb{R}^M.
\end{align}

\section*{Final Result}
\[
\boxed{A\succeq 0,\qquad A_{ab}=\left\langle \operatorname{tr}(P_a^\dagger P_b)\right\rangle}
\]
\hfill$\blacksquare$

core_reasoning_2:
\section*{Claim}
For the reflection $R(x,y,z)=(-x,y,z)$ and the antilinear operation $\Theta[P]:=R[P]^\dagger$, suppose $P_1,\ldots,P_M$ are path operators contained in $x\geq 0$ with endpoints on the mirror plane $x=0$. If
\[
A_{ab}^{\mathrm{RP}}:=\left\langle \operatorname{tr}\bigl(\Theta[P_a]P_b\bigr)\right\rangle,
\]
then $A^{\mathrm{RP}}\succeq 0$.

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \displaystyle R(x,y,z)=(-x,y,z),\qquad \Theta[P]:=R[P]^\dagger.\\[0.6em]
\text{(P2)} & \displaystyle S=S_0+S_+(U_+,U_0)+S_-(U_-,U_0),\qquad S_-(U_-,U_0)=S_+(R[U_-],U_0).\\[0.6em]
\text{(P3)} & \displaystyle \int DU\,e^{-S}\operatorname{tr}\bigl(\Theta[F]F\bigr)=\int DU_0\,e^{-S_0}\operatorname{tr}\bigl(Q(U_0)^\dagger Q(U_0)\bigr),\\[0.4em]
& \displaystyle \hfill Q(U_0):=\int DU_+\,e^{-S_+(U_+,U_0)}F(U_+,U_0).\\[0.8em]
\text{(P4)} & \displaystyle \operatorname{tr}(V^\dagger V)=\sum_{i,j=1}^N |v_{ij}|^2\geq 0\quad\text{for every complex }N\times N\text{ matrix }V.\\[0.8em]
\text{(P5)} & \displaystyle F:=\sum_{a=1}^M c_aP_a,\qquad c_a\in\mathbb{R},\qquad A_{ab}^{\mathrm{RP}}:=\left\langle \operatorname{tr}\bigl(\Theta[P_a]P_b\bigr)\right\rangle.
\end{array}
\]

\section*{Derivation}
From (P3) and (P4),
\begin{align}
\int DU\,e^{-S}\operatorname{tr}\bigl(\Theta[F]F\bigr)
&=\int DU_0\,e^{-S_0}\operatorname{tr}\bigl(Q(U_0)^\dagger Q(U_0)\bigr) && \text{by (P3)}\\
&\geq 0 && \text{by (P4) and }e^{-S_0}\geq 0.\label{rp-int-positive}
\end{align}
Dividing by $Z:=\int DU\,e^{-S}>0$ gives
\begin{align}
\left\langle \operatorname{tr}\bigl(\Theta[F]F\bigr)\right\rangle\geq 0.\label{rp-exp-positive}
\end{align}
Using the real linear combination in (P5) and the antilinearity of $\Theta$ with real coefficients,
\begin{align}
\Theta[F]
&=\Theta\left[\sum_{a=1}^M c_aP_a\right] && \text{by (P5)}\\
&=\sum_{a=1}^M c_a\Theta[P_a] && \text{real coefficients},\\
\Theta[F]F
&=\left(\sum_{a=1}^M c_a\Theta[P_a]\right)\left(\sum_{b=1}^M c_bP_b\right) && \text{substitution}\\
&=\sum_{a,b=1}^M c_a c_b\Theta[P_a]P_b && \text{distributivity},\\
\left\langle \operatorname{tr}\bigl(\Theta[F]F\bigr)\right\rangle
&=\sum_{a,b=1}^M c_a c_b\left\langle \operatorname{tr}\bigl(\Theta[P_a]P_b\bigr)\right\rangle && \text{linearity}\\
&=\sum_{a,b=1}^M c_a c_b A_{ab}^{\mathrm{RP}} && \text{by (P5)}.\label{rp-quadratic}
\end{align}
Combining \eqref{rp-exp-positive} and \eqref{rp-quadratic},
\begin{align}
\sum_{a,b=1}^M c_a c_b A_{ab}^{\mathrm{RP}}\geq 0\qquad\text{for all }c\in\mathbb{R}^M.
\end{align}

\section*{Final Result}
\[
\boxed{A^{\mathrm{RP}}\succeq 0,\qquad A_{ab}^{\mathrm{RP}}=\left\langle \operatorname{tr}\bigl(\Theta[P_a]P_b\bigr)\right\rangle}
\]
\hfill$\blacksquare$

core_reasoning_3:
\section*{Claim}
In two-dimensional lattice Yang-Mills theory, impose the gauge condition $U_{0+}=U_{0-}=1$ on the two half-lines on $x=0$. For the twist reflection $R_t(x,y)=(-x,-y)$ and $\Theta_t[P]:=R_t[P]^\dagger$, if $P_1,\ldots,P_M$ are paths in $U_+$ with endpoints at the origin, then
\[
A_{ab}^{t}:=\left\langle \operatorname{tr}\bigl(\Theta_t[P_a]P_b\bigr)\right\rangle
\]
is positive semidefinite.

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \displaystyle R_t(x,y)=(-x,-y),\qquad \Theta_t[P]:=R_t[P]^\dagger.\\[0.6em]
\text{(P2)} & \displaystyle U_+:=\{x>0\},\quad U_-:=\{x<0\},\quad U_{0+}:=\{x=0,y>0\},\quad U_{0-}:=\{x=0,y<0\}.\\[0.6em]
\text{(P3)} & \displaystyle \text{In }d=2\text{ one may impose }U_{0+}=U_{0-}=1.\\[0.6em]
\text{(P4)} & \displaystyle \int DU\,e^{-S}\operatorname{tr}\bigl(\Theta_t[F]F\bigr)=\operatorname{tr}\left(Q^\dagger Q\right),\qquad Q:=\int DU_+\,e^{-S_+(U_+)}F(U_+).\\[0.8em]
\text{(P5)} & \displaystyle \operatorname{tr}(V^\dagger V)=\sum_{i,j=1}^N |v_{ij}|^2\geq 0\quad\text{for every complex }N\times N\text{ matrix }V.\\[0.8em]
\text{(P6)} & \displaystyle F:=\sum_{a=1}^M c_aP_a,\qquad c_a\in\mathbb{R},\qquad A_{ab}^{t}:=\left\langle \operatorname{tr}\bigl(\Theta_t[P_a]P_b\bigr)\right\rangle.
\end{array}
\]

\section*{Derivation}
The gauge fixing in (P3) removes the line variables $U_{0+}$ and $U_{0-}$, so the twist-reflected half is the Hermitian conjugate of the positive half in the sense of (P4). Therefore
\begin{align}
\int DU\,e^{-S}\operatorname{tr}\bigl(\Theta_t[F]F\bigr)
&=\operatorname{tr}(Q^\dagger Q) && \text{by (P4)}\\
&\geq 0 && \text{by (P5)}.\label{trp-int-positive}
\end{align}
After normalization by $Z:=\int DU\,e^{-S}>0$,
\begin{align}
\left\langle \operatorname{tr}\bigl(\Theta_t[F]F\bigr)\right\rangle\geq 0.\label{trp-exp-positive}
\end{align}
Using (P6),
\begin{align}
\Theta_t[F]
&=\Theta_t\left[\sum_{a=1}^M c_aP_a\right] && \text{by (P6)}\\
&=\sum_{a=1}^M c_a\Theta_t[P_a] && \text{real coefficients},\\
\Theta_t[F]F
&=\left(\sum_{a=1}^M c_a\Theta_t[P_a]\right)\left(\sum_{b=1}^M c_bP_b\right) && \text{substitution}\\
&=\sum_{a,b=1}^M c_ac_b\Theta_t[P_a]P_b && \text{distributivity},\\
\left\langle \operatorname{tr}\bigl(\Theta_t[F]F\bigr)\right\rangle
&=\sum_{a,b=1}^M c_ac_b\left\langle \operatorname{tr}\bigl(\Theta_t[P_a]P_b\bigr)\right\rangle && \text{linearity}\\
&=\sum_{a,b=1}^M c_ac_b A_{ab}^{t} && \text{by (P6)}.\label{trp-quadratic}
\end{align}
Combining \eqref{trp-exp-positive} and \eqref{trp-quadratic},
\begin{align}
\sum_{a,b=1}^M c_ac_b A_{ab}^{t}\geq 0\qquad\text{for every }c\in\mathbb{R}^M.
\end{align}

\section*{Final Result}
\[
\boxed{A^{t}\succeq 0,\qquad A_{ab}^{t}=\left\langle \operatorname{tr}\bigl(\Theta_t[P_a]P_b\bigr)\right\rangle\quad(d=2)}
\]
\hfill$\blacksquare$

core_reasoning_5:
\section*{Claim}
In the large-$N$ limit, assuming factorization of products of normalized Wilson loops and equality of opposite plaquette orientations, the normalized single-trace loop equation reduces to
\[
\sum_{\pm\nu\ne\mu}\left[\left\langle w(\mu\nu\bar\mu\bar\nu C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu C)\right\rangle\right]
+2\lambda\left[\sum_{j_+=1}^{\check n_+}\langle w(C_{x,x_+})\rangle\langle w(C_{x_+,x})\rangle-\sum_{j_-=1}^{n_-}\langle w(C_{x,x_-})\rangle\langle w(C_{x_-,x})\rangle\right]=0.
\]

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \displaystyle \text{For finite }\check n_+,n_-,\quad \lim_{N\to\infty}\frac{2\lambda}{N^2}(\check n_+-n_-)=0.\\[0.8em]
\text{(P2)} & \displaystyle \left\langle w(A)w(B)\right\rangle=\left\langle w(A)\right\rangle\left\langle w(B)\right\rangle+O(N^{-2}).\\[0.8em]
\text{(P3)} & \displaystyle \left\langle w(\mu\nu\bar\mu\bar\nu)\right\rangle=\left\langle w(\nu\mu\bar\nu\bar\mu)\right\rangle.\\[0.8em]
\text{(P4)} & \displaystyle \text{The finite-}N\text{ normalized single-trace loop equation is the following identity.}
\end{array}
\]
\[
\begin{aligned}
0={}&\sum_{\pm\nu\ne\mu}\left[\left\langle w(\mu\nu\bar\mu\bar\nu C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu C)\right\rangle\right]
-\frac{2\lambda}{N^2}(\check n_+-n_-)\left\langle w(C)\right\rangle\\
&+2\lambda\left[\sum_{j_+=1}^{\check n_+}\left\langle w(C_{x,x_+})w(C_{x_+,x})\right\rangle-\sum_{j_-=1}^{n_-}\left\langle w(C_{x,x_-})w(C_{x_-,x})\right\rangle\right]\\
&-\sum_{\pm\nu\ne\mu}\left[\left\langle w(\mu\nu\bar\mu\bar\nu)w(C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu)w(C)\right\rangle\right].
\end{aligned}
\]

\section*{Derivation}
Apply (P2) to the overlap terms:
\begin{align}
\left\langle w(C_{x,x_+})w(C_{x_+,x})\right\rangle
&=\left\langle w(C_{x,x_+})\right\rangle\left\langle w(C_{x_+,x})\right\rangle+O(N^{-2}),\\
\left\langle w(C_{x,x_-})w(C_{x_-,x})\right\rangle
&=\left\langle w(C_{x,x_-})\right\rangle\left\langle w(C_{x_-,x})\right\rangle+O(N^{-2}).
\end{align}
Apply (P2) to the action-loop product terms:
\begin{align}
&\left\langle w(\mu\nu\bar\mu\bar\nu)w(C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu)w(C)\right\rangle\\
&\quad=\left\langle w(\mu\nu\bar\mu\bar\nu)\right\rangle\left\langle w(C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu)\right\rangle\left\langle w(C)\right\rangle+O(N^{-2})\\
&\quad=\left(\left\langle w(\mu\nu\bar\mu\bar\nu)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu)\right\rangle\right)\left\langle w(C)\right\rangle+O(N^{-2})\\
&\quad=O(N^{-2}) && \text{by (P3)}.
\end{align}
Apply (P1) to the explicit $N^{-2}$ term:
\begin{align}
-\frac{2\lambda}{N^2}(\check n_+-n_-)\left\langle w(C)\right\rangle\longrightarrow 0\qquad(N\to\infty).
\end{align}
Taking the $N\to\infty$ limit of (P4) and discarding the displayed $O(N^{-2})$ terms gives the claimed equation.

\section*{Final Result}
\[
\boxed{\begin{aligned}
0={}&\sum_{\pm\nu\ne\mu}\left[\left\langle w(\mu\nu\bar\mu\bar\nu C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu C)\right\rangle\right]\\
&+2\lambda\left[\sum_{j_+=1}^{\check n_+}\left\langle w(C_{x,x_+})\right\rangle\left\langle w(C_{x_+,x})\right\rangle-\sum_{j_-=1}^{n_-}\left\langle w(C_{x,x_-})\right\rangle\left\langle w(C_{x_-,x})\right\rangle\right].
\end{aligned}}
\]
\hfill$\blacksquare$

core_reasoning_6:
\section*{Claim}
In $SU(2)$ lattice Yang-Mills theory, the normalized single-trace loop equation reduces to a single-trace equation:
\[
\sum_{\pm\nu\ne\mu}\left[\left\langle w(\mu\nu\bar\mu\bar\nu C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu C)\right\rangle\right]
+\lambda\left[\frac{1}{2}(\check n_+-n_-)\left\langle w(C)\right\rangle+\sum_{j_+=1}^{\check n_+}\left\langle w(C_{x,x_+}\bar C_{x_+,x})\right\rangle-\sum_{j_-=1}^{n_-}\left\langle w(C_{x,x_-}\bar C_{x_-,x})\right\rangle\right]=0.
\]

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \displaystyle N=2.\\[0.6em]
\text{(P2)} & \displaystyle 2w(A)w(B)=w(AB)+w(A\bar B)\quad\text{for }SU(2)\text{ loops based at the same point}.\\[0.8em]
\text{(P3)} & \displaystyle w(\mu\nu\bar\mu\bar\nu)=w(\nu\mu\bar\nu\bar\mu).\\[0.8em]
\text{(P4)} & \displaystyle \text{The finite-}N\text{ single-trace equation is}
\end{array}
\]
\[
\begin{aligned}
0={}&\sum_{\pm\nu\ne\mu}\left[\left\langle w(\mu\nu\bar\mu\bar\nu C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu C)\right\rangle\right]
-\frac{2\lambda}{N^2}(\check n_+-n_-)\left\langle w(C)\right\rangle\\
&+2\lambda\left[\sum_{j_+=1}^{\check n_+}\left\langle w(C_{x,x_+})w(C_{x_+,x})\right\rangle-\sum_{j_-=1}^{n_-}\left\langle w(C_{x,x_-})w(C_{x_-,x})\right\rangle\right]\\
&-\sum_{\pm\nu\ne\mu}\left[\left\langle w(\mu\nu\bar\mu\bar\nu)w(C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu)w(C)\right\rangle\right].
\end{aligned}
\]

\section*{Derivation}
Set $N=2$ in the explicit coefficient of (P4):
\begin{align}
-\frac{2\lambda}{N^2}(\check n_+-n_-)\langle w(C)\rangle
&=-\frac{\lambda}{2}(\check n_+-n_-)\langle w(C)\rangle && \text{by (P1)}.\label{su2-coeff}
\end{align}
By (P2), each same-oriented overlap satisfies
\begin{align}
2\lambda\left\langle w(C_{x,x_+})w(C_{x_+,x})\right\rangle
&=\lambda\left\langle w(C_{x,x_+}C_{x_+,x})+w(C_{x,x_+}\bar C_{x_+,x})\right\rangle && \text{by (P2)}\\
&=\lambda\left\langle w(C)+w(C_{x,x_+}\bar C_{x_+,x})\right\rangle && \text{path concatenation}.\label{su2-plus}
\end{align}
Similarly, each opposite-oriented overlap satisfies
\begin{align}
-2\lambda\left\langle w(C_{x,x_-})w(C_{x_-,x})\right\rangle
&=-\lambda\left\langle w(C)+w(C_{x,x_-}\bar C_{x_-,x})\right\rangle && \text{by (P2)}.\label{su2-minus}
\end{align}
Summing \eqref{su2-plus} and \eqref{su2-minus} over all overlaps gives
\begin{align}
&2\lambda\left[\sum_{j_+=1}^{\check n_+}\langle w(C_{x,x_+})w(C_{x_+,x})\rangle-\sum_{j_-=1}^{n_-}\langle w(C_{x,x_-})w(C_{x_-,x})\rangle\right]\\
&\quad=\lambda(\check n_+-n_-)\langle w(C)\rangle
+\lambda\left[\sum_{j_+=1}^{\check n_+}\langle w(C_{x,x_+}\bar C_{x_+,x})\rangle-\sum_{j_-=1}^{n_-}\langle w(C_{x,x_-}\bar C_{x_-,x})\rangle\right].\label{su2-overlap-sum}
\end{align}
By (P3), the last line of (P4) vanishes term by term:
\begin{align}
\left\langle w(\mu\nu\bar\mu\bar\nu)w(C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu)w(C)\right\rangle=0.\label{su2-plaquette-product}
\end{align}
Combining \eqref{su2-coeff}, \eqref{su2-overlap-sum}, and \eqref{su2-plaquette-product} inside (P4) yields the coefficient of $\langle w(C)\rangle$:
\begin{align}
-\frac{\lambda}{2}(\check n_+-n_-)+\lambda(\check n_+-n_-)=\frac{\lambda}{2}(\check n_+-n_-).
\end{align}
The claimed equation follows.

\section*{Final Result}
\[
\boxed{\begin{aligned}
0={}&\sum_{\pm\nu\ne\mu}\left[\left\langle w(\mu\nu\bar\mu\bar\nu C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu C)\right\rangle\right]\\
&+\lambda\left[\frac{1}{2}(\check n_+-n_-)\left\langle w(C)\right\rangle+\sum_{j_+=1}^{\check n_+}\left\langle w(C_{x,x_+}\bar C_{x_+,x})\right\rangle-\sum_{j_-=1}^{n_-}\left\langle w(C_{x,x_-}\bar C_{x_-,x})\right\rangle\right].
\end{aligned}}
\]
\hfill$\blacksquare$

