\end{align}
Unlike the $SU(2)$ case, (P3) gives no identity that eliminates all double-trace terms. Therefore
\begin{align}
\left\langle w_x(C_{x,x_+})w_x(C_{x_+,x})\right\rangle,
\quad
\left\langle w_x(C_{x,x_-})w_x(C_{x_-,x})\right\rangle,
\quad
\left\langle w_x(\mu\nu\bar\mu\bar\nu)w_x(C)\right\rangle
\end{align}
remain as double-trace variables. Substituting \eqref{su3-coefficient} into (P2) and leaving the double-trace variables unreduced gives the stated equation.

\section*{Final Result}
\[
\boxed{\begin{aligned}
0={}&\sum_{\pm\nu\ne\mu}\left[\left\langle w(\mu\nu\bar\mu\bar\nu C)\right\rangle-\left\langle w(\nu\mu\bar\nu\bar\mu C)\right\rangle\right]
-\frac{2\lambda}{9}(\check n_+-n_-)\left\langle w(C)\right\rangle\\
&+2\lambda\left[\sum_{j_+=1}^{\check n_+}\left\langle w_x(C_{x,x_+})w_x(C_{x_+,x})\right\rangle-\sum_{j_-=1}^{n_-}\left\langle w_x(C_{x,x_-})w_x(C_{x_-,x})\right\rangle\right]\\
&-\sum_{\pm\nu\ne\mu}\left[\left\langle w_x(\mu\nu\bar\mu\bar\nu)w_x(C)\right\rangle-\left\langle w_x(\nu\mu\bar\nu\bar\mu)w_x(C)\right\rangle\right].
\end{aligned}}
\]
\hfill$\blacksquare$

core_reasoning_8:
\section*{Claim}
For $X,Y,Z\in SU(3)$ and normalized Wilson-loop notation $w(A):=\frac{1}{3}\operatorname{tr}(A)$, the triple-trace product reduces to single- and double-trace terms:
\[
\begin{aligned}
w(X)w(Y)w(Z)={}&-\frac{1}{9}\bigl(w(XYZ)+w(ZYX)\bigr)\\
&+\frac{1}{3}\bigl(w(X)w(YZ)+w(Y)w(ZX)+w(Z)w(XY)\bigr)\\
&+\frac{1}{3}w(X^\dagger Y)w(X^\dagger Z)-\frac{1}{9}w(X^\dagger YX^\dagger Z).
\end{aligned}
\]

\section*{Premises}
\[
