\section*{Claim}
Let $S:=\mathbb{Z}\times\{0,1\}$ be the two-dimensional ladder strip, and let $\mathcal{P}_{\mathrm{lad}}$ be the set of path words whose vertices all lie in $S$. If $P,Q\in\mathcal{P}_{\mathrm{lad}}$ have common endpoints, then the sewn loop $P^\dagger Q$ is ladder-type. Moreover, if a Schwinger-Dyson variation is applied only to a vertical edge of a ladder-type loop, every loop obtained by inserting either adjacent plaquette also remains ladder-type. Symbolically,
\[
P,Q\in\mathcal{P}_{\mathrm{lad}}\Longrightarrow P^\dagger Q\in\mathcal{L}_{\mathrm{lad}},
\qquad
C\in\mathcal{L}_{\mathrm{lad}}\Longrightarrow \operatorname{SD}_{b,\bar b}(C)\subseteq\mathcal{L}_{\mathrm{lad}}.
\]

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \displaystyle S:=\mathbb{Z}\times\{0,1\}.\\[0.6em]
\text{(P2)} & \displaystyle V(P)\text{ denotes the set of lattice vertices visited by a path or loop }P.\\[0.6em]
\text{(P3)} & \displaystyle P\in\mathcal{P}_{\mathrm{lad}}\Longleftrightarrow V(P)\subseteq S,
\qquad C\in\mathcal{L}_{\mathrm{lad}}\Longleftrightarrow C\text{ is closed and }V(C)\subseteq S.\\[0.8em]
\text{(P4)} & \displaystyle V(P^\dagger Q)=V(P)\cup V(Q)\quad\text{whenever }P,Q\text{ have common endpoints and can be sewn}.\\[0.8em]
\text{(P5)} & \displaystyle \text{A vertical edge }e\text{ of a ladder loop has endpoints }(m,0),(m,1)\text{ for some }m\in\mathbb{Z}.\\[0.8em]
\text{(P6)} & \displaystyle \begin{aligned}[t]
\Pi_L(e)&:=\{(m-1,0),(m,0),(m,1),(m-1,1)\},\\
\Pi_R(e)&:=\{(m,0),(m+1,0),(m+1,1),(m,1)\}.
\end{aligned}\\[0.8em]
\text{(P7)} & \displaystyle \operatorname{SD}_{b,\bar b}(C)\text{ inserts only the plaquette loops }\Pi_L(e)\text{ and }\Pi_R(e)\text{ at vertical edges }e\text{ of }C.
\end{array}
\]

\section*{Derivation}
First consider sewing two ladder-type paths:
\begin{align}
P,Q\in\mathcal{P}_{\mathrm{lad}}
&\Longrightarrow V(P)\subseteq S\text{ and }V(Q)\subseteq S && \text{by (P3)},\\
&\Longrightarrow V(P)\cup V(Q)\subseteq S && \text{by set inclusion},\\
&\Longrightarrow V(P^\dagger Q)\subseteq S && \text{by (P4)},\\
&\Longrightarrow P^\dagger Q\in\mathcal{L}_{\mathrm{lad}} && \text{by (P3) and common endpoints}.\label{lad-sewing}
\end{align}
Next consider a Schwinger-Dyson plaquette insertion at a vertical ladder edge $e$ with endpoints $(m,0)$ and $(m,1)$:
\begin{align}
\Pi_L(e)
&=\{(m-1,0),(m,0),(m,1),(m-1,1)\} && \text{by (P6)},\\
&\subseteq\mathbb{Z}\times\{0,1\}=S && \text{by (P1)},\\
\Pi_R(e)
&=\{(m,0),(m+1,0),(m+1,1),(m,1)\} && \text{by (P6)},\\
&\subseteq\mathbb{Z}\times\{0,1\}=S && \text{by (P1)}.\label{lad-plaquettes}
\end{align}
If $C\in\mathcal{L}_{\mathrm{lad}}$, then $V(C)\subseteq S$ by (P3). Inserting either adjacent plaquette at a vertical edge gives a new loop $C'$ whose vertices are the union of the old vertices and one adjacent plaquette:
\begin{align}
V(C')
&=V(C)\cup \Pi_L(e)\quad\text{or}\quad V(C')=V(C)\cup \Pi_R(e) && \text{by (P7)},\\
&\subseteq S && \text{by (P3) and \eqref{lad-plaquettes}},\\
&\Longrightarrow C'\in\mathcal{L}_{\mathrm{lad}} && \text{by (P3)}.\label{lad-sd}
\end{align}
Combining \eqref{lad-sewing} and \eqref{lad-sd} gives the closure relation for the ladder-type truncation:
\begin{align}
P,Q\in\mathcal{P}_{\mathrm{lad}}&\Longrightarrow P^\dagger Q\in\mathcal{L}_{\mathrm{lad}},\\
C\in\mathcal{L}_{\mathrm{lad}}&\Longrightarrow \operatorname{SD}_{b,\bar b}(C)\subseteq\mathcal{L}_{\mathrm{lad}}.
\end{align}

\section*{Final Result}
\[
\boxed{\begin{gathered}
P,Q\in\mathcal{P}_{\mathrm{lad}}\Longrightarrow P^\dagger Q\in\mathcal{L}_{\mathrm{lad}},\\
C\in\mathcal{L}_{\mathrm{lad}}\Longrightarrow \operatorname{SD}_{b,\bar b}(C)\subseteq\mathcal{L}_{\mathrm{lad}}.
\end{gathered}}
\]
\hfill$\blacksquare$

