\section*{Claim}
For the $SU(3)$ strong-coupling expansion with
\[
\beta:=\frac{9}{\lambda},\qquad K:=\frac{d(d-1)}{2},
\]
suppose
\[
\frac{\log Z_{SU(3)}}{K}=\frac{\beta^2}{36}+\frac{\beta^3}{648}-\frac{\beta^5}{93312}+\frac{(16d-113)\beta^6}{90699264}+O(\beta^7)
\]
and the plaquette Wilson loop is extracted by
\[
\langle W_1\rangle=\frac{1}{K}\frac{\partial \log Z_{SU(3)}}{\partial \beta}.
\]
Then
\[
\langle W_1\rangle=\frac{\beta}{18}+\frac{\beta^2}{216}-\frac{5\beta^4}{93312}+\frac{(16d-113)\beta^5}{15116544}+O(\beta^6),
\]
equivalently,
\[
\langle W_1\rangle=\frac{1}{2\lambda}+\frac{3}{8\lambda^2}-\frac{45}{128\lambda^4}+\frac{16d-113}{256\lambda^5}+O(\lambda^{-6}).
\]

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \displaystyle d\geq 2,\qquad \lambda>0,\qquad \beta:=\frac{9}{\lambda},\qquad K:=\frac{d(d-1)}{2}.\\[0.8em]
\text{(P2)} & \displaystyle \frac{\log Z_{SU(3)}}{K}=\frac{\beta^2}{36}+\frac{\beta^3}{648}-\frac{\beta^5}{93312}+\frac{(16d-113)\beta^6}{90699264}+O(\beta^7).\\[0.8em]
\text{(P3)} & \displaystyle \langle W_1\rangle:=\frac{1}{K}\frac{\partial \log Z_{SU(3)}}{\partial \beta}.\\[0.8em]
\text{(P4)} & \displaystyle \frac{d}{d\beta}\beta^m=m\beta^{m-1}\quad\text{for }m\in\mathbb{Z}_{>0}.\\[0.8em]
\text{(P5)} & \displaystyle \frac{d}{d\beta}O(\beta^7)=O(\beta^6)\quad\text{as }\beta\to 0.\\[0.8em]
\text{(P6)} & \displaystyle \beta^r=\left(\frac{9}{\lambda}\right)^r\quad\text{for }r\in\mathbb{Z}_{>0}.
\end{array}
\]

\section*{Derivation}
First multiply (P2) by $K$:
\begin{align}
\log Z_{SU(3)}
&=K\left(\frac{\beta^2}{36}+\frac{\beta^3}{648}-\frac{\beta^5}{93312}+\frac{(16d-113)\beta^6}{90699264}+O(\beta^7)\right) && \text{by (P2)}.\label{logz-strong}
\end{align}
Differentiate with respect to $\beta$ and divide by $K$:
\begin{align}
\langle W_1\rangle
&=\frac{1}{K}\frac{\partial}{\partial\beta}\left[K\left(\frac{\beta^2}{36}+\frac{\beta^3}{648}-\frac{\beta^5}{93312}+\frac{(16d-113)\beta^6}{90699264}+O(\beta^7)\right)\right] && \text{by (P3) and \eqref{logz-strong}},\\
&=\frac{\partial}{\partial\beta}\left(\frac{\beta^2}{36}+\frac{\beta^3}{648}-\frac{\beta^5}{93312}+\frac{(16d-113)\beta^6}{90699264}+O(\beta^7)\right) && \text{cancel }K,\\
&=\frac{2\beta}{36}+\frac{3\beta^2}{648}-\frac{5\beta^4}{93312}+\frac{6(16d-113)\beta^5}{90699264}+O(\beta^6) && \text{by (P4) and (P5)},\\
&=\frac{\beta}{18}+\frac{\beta^2}{216}-\frac{5\beta^4}{93312}+\frac{(16d-113)\beta^5}{15116544}+O(\beta^6) && \text{simplify coefficients}.\label{beta-form}
\end{align}
Now substitute $\beta=9/\lambda$:
\begin{align}
\frac{\beta}{18}
&=\frac{9}{18\lambda}=\frac{1}{2\lambda} && \text{by (P1)},\\
\frac{\beta^2}{216}
&=\frac{9^2}{216\lambda^2}=\frac{81}{216\lambda^2}=\frac{3}{8\lambda^2} && \text{by (P6)},\\
\frac{5\beta^4}{93312}
&=\frac{5\cdot 9^4}{93312\lambda^4}=\frac{32805}{93312\lambda^4}=\frac{45}{128\lambda^4} && \text{by (P6) and integer reduction},\\
\frac{(16d-113)\beta^5}{15116544}
&=\frac{(16d-113)9^5}{15116544\lambda^5}=\frac{16d-113}{256\lambda^5} && \text{by (P6) and }15116544=256\cdot 9^5.\label{lambda-terms}
\end{align}
