\begin{align}
\langle W_1\rangle
&=\frac{1}{2\lambda}+\frac{3}{8\lambda^2}-\frac{45}{128\lambda^4}+\frac{16d-113}{256\lambda^5}+O(\lambda^{-6}) && \text{because }\beta\to 0\text{ is }\lambda\to\infty.
\end{align}

\section*{Final Result}
